    final class CommunityForm extends ScrollScreen implements CommunityScreen.Receiver {
        private final CommunityScreen parent;private final List<CommunityScreen.Field> fields;private final JsonObject values;private final Consumer<JsonObject> submit;private final Map<String,String> fieldErrors=new HashMap<>();private JsonObject original;private boolean busy;private String request="",error="";private long sentAt;private final String draftKey;private final String server,account;private final dev.abros.anthub.core.DraftStore drafts;private long saveAt;private final dev.abros.anthub.core.RequestSession session=new dev.abros.anthub.core.RequestSession();private JsonObject lastValues;private boolean retryable,conflict,refreshing;private JsonObject recovered;private boolean uncertain;
        private record Cell(CommunityScreen.Field field,int row,int column,int columns,int units){}
        private final Map<String,String> playerNames=new HashMap<>();
        private static JsonArray dimensions(String selected){var keys=new LinkedHashSet<String>(List.of("minecraft:overworld","minecraft:the_nether","minecraft:the_end"));var connection=net.minecraft.client.Minecraft.getInstance().getConnection();if(connection!=null)for(var key:connection.levels())keys.add(key.location().toString());keys.add(selected);var result=new JsonArray();for(String key:keys){var item=new JsonObject();item.addProperty("value",key);item.addProperty("label",switch(key){case "minecraft:overworld"->"Обычный мир";case "minecraft:the_nether"->"Незер";case "minecraft:the_end"->"Энд";default->key;});result.add(item);}return result;}
        private boolean place(){return Json.opt(values,"kind","").equals("place");}
        private boolean hasLocation(){return !place()&&!Json.opt(values,"kind","").equals("task")&&Set.of("board","groups","events").contains(parent.section)&&(fields.stream().anyMatch(f->f.key().equals("title"))||title.getString().equals("Место"));}
        private boolean multiline(String key){return Set.of("description","text","options","terms","about","reason").contains(key);}
        private boolean full(CommunityScreen.Field field){return multiline(field.key())||Set.of("title","invitees","dimension").contains(field.key());}
        private List<Cell> layout(){var out=new ArrayList<Cell>();var shown=shownFields();int row=0;for(int i=0;i<shown.size();){var f=shown.get(i);int count=1,units=multiline(f.key())?3:2;if(f.key().equals("x")&&i+2<shown.size())count=3;else if(!full(f)&&i+1<shown.size()&&!full(shown.get(i+1))&&!shown.get(i+1).key().equals("x")&&Math.min(480,width-40)>=340)count=2;for(int c=0;c<count;c++)out.add(new Cell(shown.get(i+c),row,c,count,units));row+=units;i+=count;}return out;}
        private int contentUnits(){var cells=layout();return cells.isEmpty()?0:cells.get(cells.size()-1).row()+cells.get(cells.size()-1).units();}
        private int footerHeight(){return 54+(hasLocation()||place()?26:0)+(conflict?28:0);}
        private int panelTop(){return DialogPanel.top(height,38+contentUnits()*22+footerHeight());}
        private int panelBottom(){return height-panelTop();}
        private boolean shown(Cell cell){return cell.row()>=firstRow&&cell.row()+cell.units()<=firstRow+visibleRows;}
        private int cellWidth(Cell cell){return (Math.min(480,width-40)-(cell.columns()-1)*8)/cell.columns();}
        private int cellX(Cell cell){return (width-Math.min(480,width-40))/2+cell.column()*(cellWidth(cell)+8);}
        private String personName(String id){if(id.isBlank())return "Не назначен";return playerNames.getOrDefault(id,parent.shortName(id));}
        private void choosePlayers(CommunityScreen.Field field){
            if(field.key().equals("assignee")){var people=new JsonArray();if(parent.data.has("detail")){var group=parent.data.getAsJsonObject("detail");if(group.has("members"))for(String id:group.getAsJsonObject("members").keySet()){var person=new JsonObject();person.addProperty("uuid",id);person.addProperty("name",personName(id));people.add(person);}}
                minecraft.setScreen(new MemberPickerScreen(this,people,player->{String id=Json.str(player,"uuid");values.addProperty("assignee",id);playerNames.put(id,Json.str(player,"name"));changed();rebuildWidgets();}));
            }else{var ids=new LinkedHashSet<String>();for(String id:Json.opt(values,"invitees","").split(","))if(!id.isBlank())ids.add(id.strip());var labels=new ArrayList<String>();labels.add("Добавить игрока…");for(String id:ids)labels.add(personName(id)+" · Убрать");minecraft.setScreen(new ChoicePopup(this,"Приглашённые игроки",labels,index->{if(index==0)FeatureListScreen.pick(this,player->{if(ids.size()>=30&&!ids.contains(Json.str(player,"uuid"))){error="Можно пригласить не более 30 игроков";rebuildWidgets();return;}ids.add(Json.str(player,"uuid"));playerNames.put(Json.str(player,"uuid"),Json.str(player,"name"));values.addProperty("invitees",String.join(",",ids));changed();rebuildWidgets();});else{ids.remove(new ArrayList<>(ids).get(index-1));values.addProperty("invitees",String.join(",",ids));changed();rebuildWidgets();}}));}
        }
        private void persist(){var fieldsOnly=new JsonObject();for(var f:fields)if(values.has(f.key()))fieldsOnly.add(f.key(),values.get(f.key()).deepCopy());if(values.has("location"))fieldsOnly.add("location",values.get("location").deepCopy());if(values.has("clearLocation"))fieldsOnly.add("clearLocation",values.get("clearLocation").deepCopy());var labels=new JsonObject();playerNames.forEach(labels::addProperty);fieldsOnly.add("playerNames",labels);saveAt=0;Client.IO.submit(()->{try{drafts.save(server,account,draftKey,fieldsOnly);}catch(Exception ex){net.minecraft.client.Minecraft.getInstance().execute(()->error="Не удалось сохранить черновик");}});}
        private void changed(){saveAt=System.currentTimeMillis()+800;retryable=false;}

        CommunityForm(CommunityScreen parent,String title,List<CommunityScreen.Field> fields,JsonObject preset,Consumer<JsonObject> submit){super(Component.literal(title));this.parent=parent;fields=new ArrayList<>(fields);if(Json.opt(preset,"kind","").equals("place")){var location=preset.has("location")&&preset.get("location").isJsonObject()?preset.getAsJsonObject("location"):new JsonObject();for(String key:List.of("dimension","x","y","z","membersOnly"))if(location.has(key))preset.addProperty(key,location.get(key).getAsString());if(!preset.has("dimension"))preset.addProperty("dimension","minecraft:overworld");if(!preset.has("membersOnly"))preset.addProperty("membersOnly","false");fields.add(new CommunityScreen.Field("dimension","Измерение",160,dimensions(Json.opt(preset,"dimension","minecraft:overworld"))));for(String key:List.of("x","y","z"))fields.add(new CommunityScreen.Field(key,key.toUpperCase(),10));fields.add(new CommunityScreen.Field("membersOnly","Кто видит место",5,CommunityTools.options("false","Все","true","Участники объединения")));}this.fields=List.copyOf(fields);var identity=preset.deepCopy();identity.remove("revision");draftKey=parent.section+"|"+parent.itemId+"|"+title+"|"+identity.toString();var mc=net.minecraft.client.Minecraft.getInstance();server=mc.getCurrentServer()==null?"":mc.getCurrentServer().ip;account=Json.opt(ServerMenuClient.state,"uuid","");drafts=new dev.abros.anthub.core.DraftStore(mc.gameDirectory.toPath().resolve("anthub/drafts"));values=preset.deepCopy();original=preset.deepCopy();try{var saved=drafts.load(server,account,draftKey);if(saved.has("playerNames"))saved.getAsJsonObject("playerNames").entrySet().forEach(e->playerNames.put(e.getKey(),e.getValue().getAsString()));for(var field:fields)if(saved.has(field.key()))values.add(field.key(),saved.get(field.key()));if(saved.has("location"))values.add("location",saved.get("location"));if(saved.has("clearLocation"))values.add("clearLocation",saved.get("clearLocation"));}catch(Exception ex){error="Черновик недоступен";}try{recovered=drafts.pending(server,account,draftKey);if(recovered!=null){uncertain=true;retryable=true;error="Предыдущая отправка не подтверждена. Проверьте её безопасным повтором.";}}catch(Exception ex){error="Не удалось проверить предыдущую отправку";}for(var field:fields)if(field.options()!=null&&!values.has(field.key()))values.addProperty(field.key(),CommunityScreen.optionValue(field.options().get(0)));if(values.has("clearLocation")&&values.get("clearLocation").getAsBoolean())values.add("location",JsonNull.INSTANCE);this.submit=submit;}
        private List<CommunityScreen.Field> shownFields(){return fields.stream().filter(f->switch(f.key()){case "invitees"->Json.opt(values,"visibility","public").equals("invited");case "occurrences"->!Json.opt(values,"repeat","none").equals("none");case "item","quantity","terms"->!Json.opt(values,"trade","none").equals("none");default->true;}).toList();}
        @Override public void renderBackground(GuiGraphics g,int x,int y,float d){super.renderBackground(g,x,y,d);DialogPanel.draw(g,width,Math.min(480,width-40),panelTop(),panelBottom());}
 @Override protected void init(){int w=Math.min(480,width-40),x=(width-w)/2,bodyTop=panelTop()+38,bodyBottom=panelBottom()-footerHeight();scrollArea(contentUnits(),bodyTop,bodyBottom,22,x+w+4);
            for(var cell:layout()){if(!shown(cell))continue;var f=cell.field();int y=bodyTop+(cell.row()-firstRow)*22,cx=cellX(cell),cw=cellWidth(cell);
                if(Set.of("assignee","invitees").contains(f.key())){String selected=Json.opt(values,f.key(),"");String label=f.key().equals("assignee")?personName(selected):selected.isBlank()?"Выбрать игроков…":"Выбрано: "+selected.split(",").length+" · Изменить…";addRenderableWidget(Button.builder(Component.literal(font.plainSubstrByWidth(label,cw-30)),b->choosePlayers(f)).bounds(cx,y+13,cw-(selected.isBlank()?0:26),20).build());if(!selected.isBlank())addRenderableWidget(Button.builder(Component.literal("×"),b->{values.addProperty(f.key(),"");changed();rebuildWidgets();}).bounds(cx+cw-22,y+13,22,20).tooltip(Tooltip.create(Component.literal(f.key().equals("assignee")?"Снять назначение ответственного":"Очистить список приглашённых"))).build());
                }else if(f.options()!=null){String label=f.options().asList().stream().filter(o->CommunityScreen.optionValue(o).equals(Json.str(values,f.key()))).map(CommunityScreen::optionLabel).findFirst().orElse(Json.opt(values,f.key(),""));addRenderableWidget(Button.builder(Component.literal(font.plainSubstrByWidth(label,cw-12)),b->minecraft.setScreen(new ChoicePopup(this,f.label(),f.options().asList().stream().map(CommunityScreen::optionLabel).toList(),index->{values.addProperty(f.key(),CommunityScreen.optionValue(f.options().get(index)));changed();rebuildWidgets();}))).bounds(cx,y+13,cw,20).build());
                }else if(Set.of("startsAt","endsAt","dueAt").contains(f.key())){boolean clear=f.key().equals("dueAt")&&!Json.opt(values,f.key(),"").isBlank();addRenderableWidget(Button.builder(Component.literal(Json.opt(values,f.key(),"").isBlank()?"Выбрать дату и время…":Json.str(values,f.key())),b->minecraft.setScreen(new DateTimeScreen(this,Json.opt(values,f.key(),""),v->{values.addProperty(f.key(),v);changed();}))).bounds(cx,y+13,cw-(clear?26:0),20).build());if(clear)addRenderableWidget(Button.builder(Component.literal("×"),b->{values.addProperty(f.key(),"");changed();rebuildWidgets();}).bounds(cx+cw-22,y+13,22,20).tooltip(Tooltip.create(Component.literal("Убрать срок задачи"))).build());
                }else if(multiline(f.key())){var box=addRenderableWidget(new MultiLineEditBox(font,cx,y+13,cw,38,Component.literal(f.label()),Component.literal(f.label())));box.setCharacterLimit(f.limit());box.setValue(Json.opt(values,f.key(),""));box.setValueListener(v->{values.addProperty(f.key(),v);changed();});
                }else{var box=addRenderableWidget(new EditBox(font,cx,y+13,cw,20,Component.literal(f.label())));box.setMaxLength(f.limit());box.setValue(Json.opt(values,f.key(),""));box.setResponder(v->{values.addProperty(f.key(),v);changed();});}
            }
            if(place())addRenderableWidget(Button.builder(Component.literal("Взять мои координаты"),b->{if(minecraft.player!=null&&minecraft.level!=null){var pos=minecraft.player.blockPosition();values.addProperty("x",String.valueOf(pos.getX()));values.addProperty("y",String.valueOf(pos.getY()));values.addProperty("z",String.valueOf(pos.getZ()));values.addProperty("dimension",minecraft.level.dimension().location().toString());changed();rebuildWidgets();}}).bounds(x,panelBottom()-54,w,20).build());
            else if(hasLocation())addRenderableWidget(Button.builder(Component.literal(values.has("location")&&values.get("location").isJsonObject()&&!(values.has("clearLocation")&&values.get("clearLocation").getAsBoolean())?"Место: "+Json.opt(values.getAsJsonObject("location"),"name","указано")+" · Изменить…":"Добавить место…"),b->minecraft.setScreen(new LocationEditor(this,values.get("location"),parent.section.equals("groups")||!Json.opt(values,"group","").isEmpty()||parent.data.has("detail")&&parent.data.getAsJsonObject("detail").has("group"),location->{values.add("location",location);values.addProperty("clearLocation",location==null||location.isJsonNull());changed();}))).bounds(x,panelBottom()-54,w,20).build());
            if(conflict)addRenderableWidget(Button.builder(Component.literal("Обновить запись, сохранив текст"),b->{if(busy)return;var q=new JsonObject();q.addProperty("action","community");q.addProperty("op",values.has("itemId")?"plusItemRead":"detail");if(values.has("itemId"))q.add("itemId",values.get("itemId"));q.addProperty("section",parent.section);q.addProperty("id",parent.itemId);q=session.begin(q,false,System.currentTimeMillis());request=Json.str(q,"request");busy=true;refreshing=true;ServerMenuClient.request(q);}).bounds(x,bodyBottom+24,w,20).build());
            for(var widget:renderables)if(widget instanceof AbstractWidget input)input.active=!busy&&!uncertain;
            var save=addRenderableWidget(Button.builder(Component.literal(busy?"Отправка…":retryable?"Повторить":title.getString().startsWith("Редактировать")||title.getString().equals("Место")?"Сохранить":fields.stream().anyMatch(f->f.key().equals("title"))?"Создать":"Отправить"),b->send()).bounds(x,panelBottom()-28,w/2-3,20).build());save.active=!busy&&!conflict;addRenderableWidget(Button.builder(Component.literal("Назад"),b->onClose()).bounds(x+w/2+3,panelBottom()-28,w/2-3,20).build());}
        private void send(){if(busy)return;fieldErrors.clear();String checking="";var body=values.deepCopy();try{if(recovered!=null){body=session.begin(recovered,true,System.currentTimeMillis());recovered=null;lastValues=values.deepCopy();dispatch(body);return;}for(var f:shownFields()){checking=f.key();String value=Json.opt(values,f.key(),"").strip();if(value.isBlank()&&!(place()&&f.key().equals("description"))&&!Set.of("group","category","invitees","assignee","dueAt","about","interests").contains(f.key()))throw new IllegalArgumentException("Заполните: "+f.label());if(Set.of("days","capacity","quantity","occurrences").contains(f.key())){int n=Integer.parseInt(value);int min=f.key().equals("capacity")?0:f.key().equals("occurrences")?2:1;int max=switch(f.key()){case "days"->90;case "capacity"->300;case "occurrences"->26;default->1000000;};if(n<min||n>max)throw new IllegalArgumentException("От "+min+" до "+max);body.addProperty(f.key(),n);}if(Set.of("startsAt","endsAt","dueAt").contains(f.key())&&!value.isBlank())body.addProperty(f.key(),LocalDateTime.parse(value,DateTimeFormatter.ofPattern("uuuu-MM-dd HH:mm").withResolverStyle(java.time.format.ResolverStyle.STRICT)).atZone(ZoneId.systemDefault()).toInstant().toString());if(Set.of("startsAt","endsAt").contains(f.key())&&Instant.parse(body.get(f.key()).getAsString()).isBefore(Instant.now()))throw new IllegalArgumentException("Выберите время в будущем");if(f.key().equals("options")){var options=new JsonArray();for(String s:value.split("\\|"))options.add(s.strip());body.add("options",options);}if(Set.of("multiple","changeVote","liveResults").contains(f.key()))body.addProperty(f.key(),value.equals("Да"));}if(Json.opt(values,"visibility","").equals("group")&&Json.opt(values,"group","").isBlank()){checking="group";throw new IllegalArgumentException("Выберите объединение для закрытого события");}if(!Json.opt(values,"visibility","").equals("invited"))body.remove("invitees");if(place()){checking="x";var location=new JsonObject();location.addProperty("name",Json.opt(values,"title","").strip());location.addProperty("dimension",Json.opt(values,"dimension","").strip());for(String key:List.of("x","y","z")){checking=key;location.addProperty(key,Integer.parseInt(Json.opt(values,key,"").strip()));}location.addProperty("membersOnly",Json.opt(values,"membersOnly","false").equals("true"));body.add("location",dev.abros.anthub.core.CommunityLocation.read(location).json());body.remove("clearLocation");}if(!hasLocation()&&!place()){body.remove("location");body.remove("clearLocation");}if(retryable&&lastValues!=null&&lastValues.equals(values)){body=session.retry(System.currentTimeMillis());}else{lastValues=values.deepCopy();body=session.begin(body,true,System.currentTimeMillis());}dispatch(body);}catch(Exception ex){fieldErrors.put(checking,ex instanceof NumberFormatException?"Введите целое число":ex.getMessage());int index=0;for(var f:shownFields()){if(f.key().equals(checking))break;index++;}int row=0;for(var cell:layout())if(cell.field().key().equals(checking)){row=cell.row();break;}restoreScroll(row);error="Проверьте выделенное поле";rebuildWidgets();}}
        private String fieldValue(CommunityScreen.Field field,JsonObject source){String key=field.key();JsonElement value=source.get(key);if(source.has("trade")&&source.get("trade").isJsonObject()){var offer=source.getAsJsonObject("trade");if(key.equals("trade"))value=offer.get("type");else if(Set.of("item","quantity","terms").contains(key))value=offer.get(key);}if(value==null||value.isJsonNull())return "Не указано";String text;if(value.isJsonPrimitive()){var p=value.getAsJsonPrimitive();if(Set.of("startsAt","endsAt","dueAt").contains(key)&&p.isNumber()){long time=p.getAsLong();text=time==0?"Не указано":DateTimeFormatter.ofPattern("uuuu-MM-dd HH:mm").format(Instant.ofEpochMilli(time).atZone(ZoneId.systemDefault()));}else text=p.isBoolean()?(p.getAsBoolean()?"Да":"Нет"):p.getAsString();}else if(value.isJsonArray()){text=String.join(" | ",value.getAsJsonArray().asList().stream().map(JsonElement::getAsString).toList());}else text="Изменено";if(field.options()!=null)for(var option:field.options())if(CommunityScreen.optionValue(option).equals(text))return CommunityScreen.optionLabel(option);return text.isBlank()?"Не указано":text;}
        private void dispatch(JsonObject body){request=Json.str(body,"request");persist();busy=true;uncertain=true;sentAt=System.currentTimeMillis();error="";var pending=session.command();Client.IO.submit(()->{try{drafts.pending(server,account,draftKey,pending);net.minecraft.client.Minecraft.getInstance().execute(()->{submit.accept(body);});}catch(Exception ex){net.minecraft.client.Minecraft.getInstance().execute(()->{session.cancel();busy=false;uncertain=false;error="Не удалось сохранить состояние отправки. Запрос не отправлен.";rebuildWidgets();});}});rebuildWidgets();}
        public void receiveCommunity(JsonObject j){if(!session.receive(j))return;busy=false;uncertain=j.has("error")&&!Set.of("CONFLICT","INVALID","FORBIDDEN","EXPIRED","NOT_FOUND").contains(Json.opt(j,"code",""));if(!uncertain)Client.IO.submit(()->{try{drafts.pending(server,account,draftKey,null);}catch(Exception ignored){}});if(j.has("error")){error=Json.opt(j,"text","Ошибка");conflict=Json.opt(j,"code","").equals("CONFLICT");refreshing=false;retryable=!Set.of("CONFLICT","INVALID","FORBIDDEN","EXPIRED").contains(Json.opt(j,"code",""));rebuildWidgets();return;}if(refreshing){refreshing=false;conflict=false;retryable=false;var latest=j.has("item")?j.getAsJsonObject("item"):j.getAsJsonObject("detail");values.add(j.has("item")?"itemRevision":"revision",latest.get("revision"));var differences=new ArrayList<String>();for(var field:fields){String key=field.key();String current=fieldValue(field,latest),before=fieldValue(field,original);if(!current.equals(before))differences.add(field.label()+"\nСейчас на сервере: "+current+"\nВаш вариант: "+fieldValue(field,values));}original=latest.deepCopy();error="Сохранён ваш вариант. Проверьте изменения перед отправкой.";rebuildWidgets();if(!differences.isEmpty())minecraft.setScreen(new TextScreen(this,Component.literal("Запись изменена другим игроком"),String.join("\n\n",differences)));return;}Client.IO.submit(()->{try{drafts.remove(server,account,draftKey);}catch(Exception ignored){}});saveAt=0;minecraft.setScreen(parent.surface());parent.busy=false;parent.invalidate();}
        @Override public boolean mouseScrolled(double x,double y,double dx,double dy){for(var child:children())if(child instanceof MultiLineEditBox edit&&edit.isMouseOver(x,y)&&edit.mouseScrolled(x,y,dx,dy))return true;return super.mouseScrolled(x,y,dx,dy);}
        @Override public void render(GuiGraphics g,int x,int y,float d){super.render(g,x,y,d);g.drawCenteredString(font,title,width/2,panelTop()+14,0xE2BE75);for(var cell:layout()){if(!shown(cell))continue;int cy=panelTop()+38+(cell.row()-firstRow)*22;String issue=fieldErrors.get(cell.field().key());String label=issue==null?cell.field().label():issue;g.drawString(font,font.plainSubstrByWidth(label,cellWidth(cell)),cellX(cell),cy,issue==null?0xEEEEEE:0xFF7777);}Ui.status(g,font,error,(width-Math.min(480,width-40))/2,panelBottom()-footerHeight()+2,Math.min(480,width-40),panelBottom()-footerHeight()+22);}
        @Override public void onClose(){persist();session.cancel();minecraft.setScreen(parent.surface());}
        @Override public void tick(){if(saveAt>0&&System.currentTimeMillis()>=saveAt)persist();if(!ServerMenuClient.available()){persist();minecraft.setScreen(null);}else if(session.timeout(System.currentTimeMillis())){if(refreshing){refreshing=false;busy=false;conflict=true;error="Обновление не удалось. Попробуйте ещё раз.";rebuildWidgets();return;}busy=false;uncertain=true;retryable=true;error="Ответ не получен. Повтор безопасен: действие не продублируется.";rebuildWidgets();}}
        @Override public boolean isPauseScreen(){return false;}
    }
